OPS = {"+": "ADD", "-": "SUB", "*": "MUL", "<": "LT", "<=": "LE"}

def ref_compile_expr(node, code):
    if node[0] == "num":
        code.append(("PUSH", node[1]))
    elif node[0] == "var":
        code.append(("LOAD", node[1]))
    else:
        ref_compile_expr(node[2], code)
        ref_compile_expr(node[3], code)
        code.append((OPS[node[1]],))

def ref_run(code):
    pc, stack, env, out = 0, [], {}, []
    while True:
        op = code[pc]
        pc += 1
        name = op[0]
        if name == "PUSH":
            stack.append(op[1])
        elif name == "LOAD":
            stack.append(env[op[1]])
        elif name == "STORE":
            env[op[1]] = stack.pop()
        elif name == "PRINT":
            out.append(stack.pop())
        elif name == "JUMP":
            pc = op[1]
        elif name == "JUMP_IF_FALSE":
            if not stack.pop():
                pc = op[1]
        elif name == "HALT":
            return out
        else:
            b, a = stack.pop(), stack.pop()
            if name == "ADD":
                stack.append(a + b)
            elif name == "SUB":
                stack.append(a - b)
            elif name == "MUL":
                stack.append(a * b)
            elif name == "LT":
                stack.append(a < b)
            else:
                stack.append(a <= b)

import bisect
import math
import re

MAX_KEYS = 3

def bt_node(keys=None, vals=None, kids=None):
    return {"keys": keys or [], "vals": vals or [], "kids": kids or []}

def _bt_split(node):
    m = len(node["keys"]) // 2
    left = bt_node(node["keys"][:m], node["vals"][:m], node["kids"][:m + 1])
    right = bt_node(node["keys"][m + 1:], node["vals"][m + 1:], node["kids"][m + 1:])
    return left, node["keys"][m], node["vals"][m], right

def _bt_ins(node, key, val):
    i = bisect.bisect_left(node["keys"], key)
    if i < len(node["keys"]) and node["keys"][i] == key:
        node["vals"][i] = val
        return None
    if not node["kids"]:
        node["keys"].insert(i, key)
        node["vals"].insert(i, val)
    else:
        r = _bt_ins(node["kids"][i], key, val)
        if r:
            left, k, v, right = r
            node["kids"][i:i + 1] = [left, right]
            node["keys"].insert(i, k)
            node["vals"].insert(i, v)
    if len(node["keys"]) > MAX_KEYS:
        return _bt_split(node)
    return None

def bt_insert(root, key, val):
    r = _bt_ins(root, key, val)
    if r:
        left, k, v, right = r
        return bt_node([k], [v], [left, right])
    return root

def bt_height(node):
    return 1 + bt_height(node["kids"][0]) if node["kids"] else 1

