def simplify(t):
    if not isinstance(t, tuple) or len(t) == 2:
        return t
    op, a, b = t[0], simplify(t[1]), simplify(t[2])
    if op == "*":
        if a == 0 or b == 0:
            return 0.0
        if a == 1:
            return b
        if b == 1:
            return b
    if op == "+":
        if a == 0:
            return b
        if b == 0:
            return a
    return (op, a, b)

